import{_ as n,a0 as p,w as h,s as o,ao as u,I as a,x as s,a1 as e,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 中安装并使用 PuTTY | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中安装并使用 PuTTY | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中安装并使用 PuTTY | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中安装并使用 PuTTY | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190208 How To Install And Use PuTTY On Linux","title":"在 Linux 中安装并使用 PuTTY","tag":"201902","desc":""},"relativePath":"201902/20190208 How To Install And Use PuTTY On Linux.md","filePath":"[post].md"}'),d={name:"201902/20190208 How To Install And Use PuTTY On Linux.md"};function k(r,i,c,g,T,F){const t=p("Link");return h(),o("div",null,[i[15]||(i[15]=u('<h1 id="在-linux-中安装并使用-putty" tabindex="-1">在 Linux 中安装并使用 PuTTY <a class="header-anchor" href="#在-linux-中安装并使用-putty" aria-label="Permalink to “在 Linux 中安装并使用 PuTTY”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/putty-720x340.png" alt=""></p><p>PuTTY 是一个自由开源且支持包括 SSH、Telnet 和 Rlogin 在内的多种协议的 GUI 客户端。一般来说，Windows 管理员们会把 PuTTY 当成 SSH 或 Telnet 客户端来在本地 Windows 系统和远程 Linux 服务器之间建立连接。不过，PuTTY 可不是 Windows 的独占软件。它在 Linux 用户之中也是很流行的。本篇文章将会告诉你如何在 Linux 中安装并使用 PuTTY。</p><h3 id="在-linux-中安装-putty" tabindex="-1">在 Linux 中安装 PuTTY <a class="header-anchor" href="#在-linux-中安装-putty" aria-label="Permalink to “在 Linux 中安装 PuTTY”">​</a></h3><p>PuTTY 已经包含在了许多 Linux 发行版的官方源中。举个例子，在 Arch Linux 中，我们可以通过这个命令安装 PuTTY：</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> putty</span></span></code></pre></div><p>在 Debian、Ubuntu 或是 Linux Mint 中安装它：</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> putty</span></span></code></pre></div><h3 id="使用-putty-访问远程-linux-服务器" tabindex="-1">使用 PuTTY 访问远程 Linux 服务器 <a class="header-anchor" href="#使用-putty-访问远程-linux-服务器" aria-label="Permalink to “使用 PuTTY 访问远程 Linux 服务器”">​</a></h3><p>在安装完 PuTTY 之后，你可以在菜单或启动器中打开它。如果你想用终端打开它，也是可以的：</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">putty</span></span></code></pre></div><p>PuTTY 的默认界面长这个样子：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/putty-default-interface.png" alt="PuTTY 默认界面"></p><p>如你所见，许多选项都配上了说明。在左侧面板中，你可以配置许多项目，比如：</p><ol><li>修改 PuTTY 登录会话选项；</li><li>修改终端模拟器控制选项，控制各个按键的功能；</li><li>控制终端响铃的声音；</li><li>启用/禁用终端的高级功能；</li><li>设定 PuTTY 窗口大小；</li><li>控制命令回滚长度（默认是 2000 行）；</li><li>修改 PuTTY 窗口或光标的外观；</li><li>调整窗口边缘；</li><li>调整字体；</li><li>保存登录信息；</li><li>设置代理；</li><li>修改各协议的控制选项；</li><li>以及更多。</li></ol><p>所有选项基本都有注释，相信你理解起来不难。</p><h3 id="使用-putty-访问远程-linux-服务器-1" tabindex="-1">使用 PuTTY 访问远程 Linux 服务器 <a class="header-anchor" href="#使用-putty-访问远程-linux-服务器-1" aria-label="Permalink to “使用 PuTTY 访问远程 Linux 服务器”">​</a></h3><p>请在左侧面板点击 “Session” 选项卡，输入远程主机名（或 IP 地址）。然后，请选择连接类型（比如 Telnet、Rlogin 以及 SSH 等）。根据你选择的连接类型，PuTTY 会自动选择对应连接类型的默认端口号（比如 SSH 是 22、Telnet 是 23），如果你修改了默认端口号，别忘了手动把它输入到 “Port” 里。在这里，我用 SSH 连接到远程主机。在输入所有信息后，请点击 “Open”。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/02/putty-1.png" alt="通过 SSH 连接"></p><p>如果这是你首次连接到这个远程主机，PuTTY 会显示一个安全警告，问你是否信任你连接到的远程主机。点击 “Accept” 即可将远程主机的密钥加入 PuTTY 的缓存当中：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/02/putty-2.png" alt="PuTTY 安全警告"></p><p>接下来，输入远程主机的用户名和密码。然后你就成功地连接上远程主机啦。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/putty-3.png" alt="已连接上远程主机"></p><h4 id="使用密钥验证访问远程主机" tabindex="-1">使用密钥验证访问远程主机 <a class="header-anchor" href="#使用密钥验证访问远程主机" aria-label="Permalink to “使用密钥验证访问远程主机”">​</a></h4><p>一些 Linux 管理员可能在服务器上配置了密钥认证。举个例子，在用 PuTTY 访问 AMS 实例的时候，你需要指定密钥文件的位置。PuTTY 可以使用它自己的格式（<code>.ppk</code> 文件）来进行公钥验证。</p><p>首先输入主机名或 IP。之后，在 “Category” 选项卡中，展开 “Connection”，再展开 “SSH”，然后选择 “Auth”，之后便可选择 <code>.ppk</code> 密钥文件了。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/02/putty-4.png" alt=""></p><p>点击 “Accept” 来关闭安全提示。然后，输入远程主机的密码（如果密钥被密码保护）来建立连接。</p><h4 id="保存-putty-会话" tabindex="-1">保存 PuTTY 会话 <a class="header-anchor" href="#保存-putty-会话" aria-label="Permalink to “保存 PuTTY 会话”">​</a></h4><p>有些时候，你可能需要多次连接到同一个远程主机，你可以保存这些会话并在之后不输入信息访问他们。</p><p>请输入主机名（或 IP 地址），并提供一个会话名称，然后点击 “Save”。如果你有密钥文件，请确保你在点击 “Save” 按钮之前指定它们。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/02/putty-5.png" alt=""></p><p>现在，你可以通过选择 “Saved sessions”，然后点击 “Load”，再点击 “Open” 来启动连接。</p><h4 id="使用-putty-安全复制客户端-pscp-来将文件传输到远程主机中" tabindex="-1">使用 PuTTY 安全复制客户端（pscp）来将文件传输到远程主机中 <a class="header-anchor" href="#使用-putty-安全复制客户端-pscp-来将文件传输到远程主机中" aria-label="Permalink to “使用 PuTTY 安全复制客户端（pscp）来将文件传输到远程主机中”">​</a></h4><p>通常来说，Linux 用户和管理员会使用 <code>scp</code> 这个命令行工具来从本地往远程主机传输文件。不过 PuTTY 给我们提供了一个叫做 <ruby>PuTTY 安全复制客户端<rt>PuTTY Secure Copy Client</rt></ruby>（简写为 <code>pscp</code>）的工具来干这个事情。如果你的本地主机运行的是 Windows，你可能需要这个工具。PSCP 在 Windows 和 Linux 下都是可用的。</p><p>使用这个命令来将 <code>file.txt</code> 从本地的 Arch Linux 拷贝到远程的 Ubuntu 上：</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pscp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.ppk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sk@192.168.225.22:/home/sk/</span></span></code></pre></div><p>让我们来分析这个命令：</p><ul><li><code>-i test.ppk</code>：访问远程主机所用的密钥文件；</li><li><code>file.txt</code>：要拷贝到远程主机的文件；</li><li><code>sk@192.168.225.22</code>：远程主机的用户名与 IP；</li><li><code>/home/sk/</code>：目标路径。</li></ul><p>要拷贝一个目录，请使用 <code>-r</code>（<ruby>递归<rt>Recursive</rt></ruby>）参数：</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pscp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.ppk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dir/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sk@192.168.225.22:/home/sk/</span></span></code></pre></div><p>要使用 <code>pscp</code> 传输文件，请执行以下命令：</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pscp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.ppk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> c:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ocuments</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ile.txt.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sk@192.168.225.22:/home/sk/</span></span></code></pre></div><p>你现在应该了解了 PuTTY 是什么，知道了如何安装它和如何使用它。同时，你也学习到了如何使用 <code>pscp</code> 程序在本地和远程主机上传输文件。</p><p>以上便是所有了，希望这篇文章对你有帮助。</p><p>干杯！</p><hr>',47)),a("p",null,[i[1]||(i[1]=s("via: ",-1)),e(t,{href:"https://www.ostechnix.com/how-to-install-and-use-putty-on-linux/"},{default:l(()=>[...i[0]||(i[0]=[s("https://www.ostechnix.com/how-to-install-and-use-putty-on-linux/",-1)])]),_:1})]),a("p",null,[i[6]||(i[6]=s("作者：",-1)),e(t,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...i[2]||(i[2]=[s("SK",-1)])]),_:1}),i[7]||(i[7]=s(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...i[3]||(i[3]=[s("lujun9972",-1)])]),_:1}),i[8]||(i[8]=s(" 译者：",-1)),e(t,{href:"https://github.com/zhs852"},{default:l(()=>[...i[4]||(i[4]=[s("zhs852",-1)])]),_:1}),i[9]||(i[9]=s(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:l(()=>[...i[5]||(i[5]=[s("wxy",-1)])]),_:1})]),a("p",null,[i[12]||(i[12]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[10]||(i[10]=[s("LCTT",-1)])]),_:1}),i[13]||(i[13]=s(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:l(()=>[...i[11]||(i[11]=[s("Linux中国",-1)])]),_:1}),i[14]||(i[14]=s(" 荣誉推出",-1))])])}const b=n(d,[["render",k]]);export{C as __pageData,b as default};
